steps:
STEP 3 — Append CYP2D6 TCA rules to data/rules/pgx.json (rules array). ALL rules: module='pgx', version='2.0.0', status='verified', evidenceLevel=null, blocking=true, onUnmetContext='conditional', requires={}. Use the exact drug IDs, gene IDs, and phenotype values from data/drugs.json and data/genes.json (confirmed: CYP2D6 phenotypes are ultrarapid/normal/intermediate/poor).

  AMITRIPTYLINE — CYP2D6:
  R-PGX-AMITRIPTYLINE-CYP2D6-UMPM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['ultrarapid','poor']}, action='modify', headline='Alternative TCA or dose adjustment recommended for CYP2D6 ultrarapid/poor metabolizers taking amitriptyline', rationale='CPIC recommends an alternative drug for CYP2D6 ultrarapid or poor metabolizers (altered amitriptyline/nortriptyline ratio); DPWG recommends decreasing the dose.', mechanism='CYP2D6 converts amitriptyline to nortriptyline; UM increases nortriptyline exposure, PM reduces it, altering efficacy and toxicity risk.', monitoring=['Plasma concentration monitoring of amitriptyline and nortriptyline if drug is continued (per guideline).'], limitations=['CPIC recommends a specific alternative; DPWG allows dose reduction. No dose is calculated here.'], evidence=['E-CPIC-TCA-2017','G:PA166105006','G:PA166104982'], alternatives={supported:true, text:'Alternative TCA (CPIC); specific agents not encoded.', evidence:['G:PA166105006']}

  R-PGX-AMITRIPTYLINE-CYP2D6-IM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['intermediate']}, action='modify', headline='Dose reduction of amitriptyline advised for CYP2D6 intermediate metabolizers', rationale='DPWG recommends decreasing the dose for CYP2D6 intermediate metabolizers of amitriptyline; CPIC similarly recommends considering a dose adjustment.', mechanism='Partial CYP2D6 activity raises nortriptyline accumulation moderately.', evidence=['E-CPIC-TCA-2017','G:PA166105006','G:PA166104982'], alternatives={supported:false, text:'No specific alternative encoded; see guidelines.'}

  AMITRIPTYLINE — CYP2C19:
  R-PGX-AMITRIPTYLINE-CYP2C19-UMRPM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid','rapid','poor']}, action='modify', headline='Alternative TCA or dose adjustment recommended for CYP2C19 ultrarapid/rapid/poor metabolizers taking amitriptyline', rationale='CPIC recommends an alternative drug for CYP2C19 ultrarapid, rapid, and poor metabolizers because CYP2C19 also metabolizes amitriptyline; note that DPWG has no specific dose recommendation for amitriptyline based on CYP2C19 genotype alone (G:PA166184526).', mechanism='CYP2C19 contributes to amitriptyline demethylation; altered activity affects parent drug and active metabolite balance.', evidence=['E-CPIC-TCA-2017','G:PA166105006'], limitations=['DPWG does not recommend a CYP2C19-specific dose change for amitriptyline (PA166184526). Encoded from CPIC only.'], alternatives={supported:true, text:'Alternative TCA (CPIC); specific agents not encoded.', evidence:['G:PA166105006']}

  NORTRIPTYLINE — CYP2D6 (similar pattern — CYP2C19 not a primary metabolising enzyme for nortriptyline):
  R-PGX-NORTRIPTYLINE-CYP2D6-UMPM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['ultrarapid','poor']}, action='modify', headline='Alternative TCA or dose adjustment recommended for CYP2D6 ultrarapid/poor metabolizers taking nortriptyline', evidence=['E-CPIC-TCA-2017','G:PA166104998','G:PA166104961'], alternatives={supported:true, text:'Alternative TCA (CPIC); specific agents not encoded.', evidence:['G:PA166104998']}

  R-PGX-NORTRIPTYLINE-CYP2D6-IM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['intermediate']}, action='modify', headline='25% dose reduction of nortriptyline advised for CYP2D6 intermediate metabolizers', evidence=['E-CPIC-TCA-2017','G:PA166104998','G:PA166104961'], alternatives={supported:false}

  CLOMIPRAMINE — CYP2D6:
  R-PGX-CLOMIPRAMINE-CYP2D6-UMPM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['ultrarapid','poor']}, action='modify', headline='Alternative TCA or dose adjustment recommended for CYP2D6 ultrarapid/poor metabolizers taking clomipramine', evidence=['E-CPIC-TCA-2017','G:PA166105007','G:PA166104964'], alternatives={supported:true, text:'Alternative TCA (CPIC); specific agents not encoded.', evidence:['G:PA166105007']}

  R-PGX-CLOMIPRAMINE-CYP2D6-IM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['intermediate']}, action='modify', headline='Dose adjustment of clomipramine advised for CYP2D6 intermediate metabolizers', evidence=['E-CPIC-TCA-2017','G:PA166105007','G:PA166104964'], alternatives={supported:false}

  CLOMIPRAMINE — CYP2C19 (DPWG PA166184528 says avoid for OCD indication; CPIC PA166105007 defers to amitriptyline guideline):
  R-PGX-CLOMIPRAMINE-CYP2C19-UM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid']}, action='modify', headline='Alternative or dose adjustment advised for CYP2C19 ultrarapid metabolizers taking clomipramine', rationale='DPWG recommends avoiding clomipramine in CYP2C19 ultrarapid metabolizers for OCD and depression indications; CPIC recommends applying the amitriptyline/nortriptyline guideline (alternative TCA for UM).', limitations=['DPWG recommends avoidance specifically for OCD/depression indications; the indication cannot be confirmed from available inputs so this is encoded as modify, not avoid.'], evidence=['E-CPIC-TCA-2017','G:PA166105007','G:PA166184528'], alternatives={supported:true, text:'Alternative TCA (DPWG/CPIC); specific agents not encoded.', evidence:['G:PA166184528']}

  DESIPRAMINE — CYP2D6:
  R-PGX-DESIPRAMINE-CYP2D6-UMPM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['ultrarapid','poor']}, action='modify', headline='Alternative TCA or dose adjustment recommended for CYP2D6 ultrarapid/poor metabolizers taking desipramine', evidence=['E-CPIC-TCA-2017','G:PA166105002'], alternatives={supported:true, text:'Alternative TCA (CPIC); specific agents not encoded.', evidence:['G:PA166105002']}

  R-PGX-DESIPRAMINE-CYP2D6-IM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['intermediate']}, action='modify', headline='Dose adjustment of desipramine advised for CYP2D6 intermediate metabolizers', evidence=['E-CPIC-TCA-2017','G:PA166105002'], alternatives={supported:false}

  IMIPRAMINE — CYP2D6:
  R-PGX-IMIPRAMINE-CYP2D6-UMPM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['ultrarapid','poor']}, action='modify', headline='Alternative TCA or dose adjustment recommended for CYP2D6 ultrarapid/poor metabolizers taking imipramine', rationale='DPWG recommends CYP2D6 poor metabolizers receive 30% of the standard dose; ultrarapid metabolizers need dose adjustment; CPIC recommends applying the amitriptyline guideline (alternative drug for UM/PM).', evidence=['E-CPIC-TCA-2017','G:PA166104999','G:PA166104972'], alternatives={supported:true, text:'Alternative TCA (CPIC); specific agents not encoded.', evidence:['G:PA166104999']}

  R-PGX-IMIPRAMINE-CYP2D6-IM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['intermediate']}, action='modify', headline='Dose reduction of imipramine advised for CYP2D6 intermediate metabolizers', rationale='DPWG recommends 70% of the standard dose for CYP2D6 intermediate metabolizers of imipramine.', evidence=['E-CPIC-TCA-2017','G:PA166104999','G:PA166104972'], alternatives={supported:false}

  IMIPRAMINE — CYP2C19:
  R-PGX-IMIPRAMINE-CYP2C19-PM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['poor']}, action='modify', headline='Dose reduction of imipramine advised for CYP2C19 poor metabolizers', rationale='DPWG recommends that CYP2C19 poor metabolizers receive 70% of the standard dose of imipramine, or that imipramine be avoided in these patients.', evidence=['E-CPIC-TCA-2017','G:PA166104999','G:PA166104954'], alternatives={supported:true, text:'Avoidance of imipramine is an option per DPWG; alternative TCA not specified.', evidence:['G:PA166104954']}

STEP 4 — Append CYP2C19 SSRI rules to data/rules/pgx.json. Same schema conventions as above.

  CITALOPRAM — CYP2C19:
  R-PGX-CITALOPRAM-CYP2C19-UM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid','rapid']}, action='modify', headline='Dose adjustment recommended for CYP2C19 ultrarapid/rapid metabolizers taking citalopram', rationale='CPIC recommends a clinically appropriate dose modification for CYP2C19 ultrarapid and rapid metabolizers (reduced efficacy at standard doses); DPWG provides similar guidance.', evidence=['E-CPIC-SSRI-2023','G:PA166127638','G:PA166104977'], alternatives={supported:false}

  R-PGX-CITALOPRAM-CYP2C19-IMPM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['intermediate','poor']}, action='modify', headline='Dose reduction recommended for CYP2C19 intermediate/poor metabolizers taking citalopram', rationale='DPWG recommends not exceeding the in-house maximum dose for CYP2C19 intermediate and poor metabolizers of citalopram (accumulation risk); CPIC similarly advises dose adjustment.', evidence=['E-CPIC-SSRI-2023','G:PA166127638','G:PA166104977'], alternatives={supported:false}

  ESCITALOPRAM — CYP2C19:
  R-PGX-ESCITALOPRAM-CYP2C19-UM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid','rapid']}, action='modify', headline='Dose adjustment recommended for CYP2C19 ultrarapid/rapid metabolizers taking escitalopram', evidence=['E-CPIC-SSRI-2023','G:PA166127638','G:PA166104975'], alternatives={supported:false}

  R-PGX-ESCITALOPRAM-CYP2C19-IMPM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['intermediate','poor']}, action='modify', headline='Dose reduction recommended for CYP2C19 intermediate/poor metabolizers taking escitalopram', rationale='DPWG recommends not exceeding the in-house maximum dose for CYP2C19 IM and PM patients taking escitalopram; CPIC advises dose adjustment.', evidence=['E-CPIC-SSRI-2023','G:PA166127638','G:PA166104975'], alternatives={supported:false}

  SERTRALINE — CYP2C19:
  R-PGX-SERTRALINE-CYP2C19-UM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid','rapid']}, action='modify', headline='Dose adjustment recommended for CYP2C19 ultrarapid/rapid metabolizers taking sertraline', rationale='CPIC recommends considering a 50% reduction of the recommended starting dose for CYP2C19 ultrarapid/rapid metabolizers (sertraline is partly metabolised by CYP2C19; reduced efficacy at standard doses).', evidence=['E-CPIC-SSRI-2023','G:PA166127639','G:PA166104980'], alternatives={supported:false}

  R-PGX-SERTRALINE-CYP2C19-PM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['poor']}, action='modify', headline='Dose reduction recommended for CYP2C19 poor metabolizers taking sertraline', rationale='DPWG recommends not exceeding 75 mg/day for CYP2C19 poor metabolizer genotypes; CPIC recommends a 50% starting dose reduction.', limitations=['TODO: Verify whether the 75 mg/day limit applies to IM as well; only PM is encoded in this version per the available DPWG summary.'], evidence=['E-CPIC-SSRI-2023','G:PA166127639','G:PA166104980'], alternatives={supported:false}
